//! DS2-codecs: compressor parity tests.
//!
//! Reference vectors were produced by the exact Java libraries the Scala datastore uses:
//! blosc-java 0.3-1.21.6 (JNI c-blosc 1.21.6, numthreads 1), commons-compress 1.28
//! `BlockLZ4CompressorOutputStream`, lz4-java 1.11.2 (native fast/high compressors), zstd-jni
//! 1.5.7-15 (`ZstdOutputStream` with checksum) and `java.util.zip`. The inputs are regenerated by
//! [`generate`], a port of the generator in the Java oracle program
//! (see checkpoints/datastore-ds2-codecs.md).

use serde_json::json;
use webknossos_datastore::compression::{
    BloscCname, BloscConfig, BloscShuffle, CompressionSetting, CompressionSettings, Compressor,
    wkw_compress_block, wkw_decompress_block,
};

struct BloscVector {
    cname: &'static str,
    clevel: i32,
    shuffle: i32,
    typesize: usize,
    blocksize: i32,
    kind: u8,
    len: usize,
    compressed: &'static [&'static str],
}

const WORDS: [&str; 12] = [
    "alpha ",
    "beta ",
    "gamma ",
    "delta ",
    "neuron ",
    "synapse ",
    "axon ",
    "dendrite ",
    "volume ",
    "skeleton ",
    "\n",
    "0123456789 ",
];

fn mix(j: u64) -> u64 {
    let mut x = 0x9E37_79B9_7F4A_7C15u64.wrapping_mul(j + 1);
    x ^= x >> 31;
    x = x.wrapping_mul(0xBF58_476D_1CE4_E5B9);
    x ^= x >> 29;
    x
}

/// Port of `Gen.gen(kind, n, ts)` from the Java oracle.
fn generate(kind: u8, n: usize, ts: usize) -> Vec<u8> {
    if kind == 2 || kind == 3 {
        let period = if kind == 2 { 9000.min(n) } else { n };
        let mut text = String::new();
        let mut k = 0u64;
        while text.len() < period {
            text.push_str(WORDS[((mix(k) >> 33) % WORDS.len() as u64) as usize]);
            k += 1;
        }
        let text = text.as_bytes();
        return (0..n).map(|i| text[i % period]).collect();
    }
    (0..n)
        .map(|i| match kind {
            0 => {
                let (e, b) = ((i / ts) as u64, i % ts);
                let v = e / 3 + (e * e % 7);
                if b < 8 { (v >> (8 * b)) as u8 } else { 0 }
            }
            1 => (mix(i as u64) >> 56) as u8,
            5 => ((i / 1000) & 0xff) as u8,
            _ => {
                if i % ts == 0 {
                    (mix(i as u64) >> 56) as u8
                } else {
                    7
                }
            }
        })
        .collect()
}

fn unhex(parts: &[&str]) -> Vec<u8> {
    let hex: String = parts.concat();
    (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
        .collect()
}

fn settings(value: serde_json::Value) -> CompressionSettings {
    serde_json::from_value(value).unwrap()
}

fn blosc(cname: BloscCname, clevel: i32, shuffle: BloscShuffle, typesize: i32) -> Compressor {
    Compressor::Blosc(BloscConfig {
        cname,
        clevel,
        shuffle,
        blocksize: 0,
        typesize,
    })
}

